#!/usr/bin/env bash

# Compares the `THIRD-PARTY.txt` files generated by `license:add-third-party`.
# The goal runs after the `compile` phase, such that the project's own modules
# are resolved from the reactor.

set -e -u -o pipefail

function probe() {
  mvn -N org.apache.maven.plugins:maven-help-plugin:3.6.0:evaluate -Dexpression='project.build.pluginManagement.pluginsAsMap(org.codehaus.mojo:license-maven-plugin).version' -q -DforceStdout
}

function collect() {
  mvn compile license:add-third-party -Dverification.skip >&2
  tail -n +1 -- */target/generated-sources/license/THIRD-PARTY.txt
}
